import re
from datetime import datetime
from collections import defaultdict

# Ay isimleri (Türkçe)
AYLAR = {
    "ocak": 1, "şubat": 2, "mart": 3, "nisan": 4,
    "mayıs": 5, "haziran": 6, "temmuz": 7, "ağustos": 8,
    "eylül": 9, "ekim": 10, "kasım": 11, "aralık": 12
}

def parse_tutar(val):
    """tutar değerini float olarak döndürür, çözümlenemezse None."""
    if val is None:
        return None
    if isinstance(val, (int, float)):
        return float(val)
    if isinstance(val, str):
        s = val.strip()
        # ₺, TL ve boşlukları at
        s = re.sub(r'₺|TL', '', s, flags=re.IGNORECASE)
        s = s.strip()
        if not s:
            return None
        # hem nokta hem virgül var → nokta binlik, virgül ondalık
        if '.' in s and ',' in s:
            s = s.replace('.', '')  # binlik noktaları sil
            s = s.replace(',', '.')  # virgülü ondalık nokta yap
            try:
                return float(s)
            except ValueError:
                return None
        # yalnız virgül
        elif ',' in s and '.' not in s:
            try:
                return float(s.replace(',', '.'))
            except ValueError:
                return None
        # yalnız nokta
        elif s.count('.') == 1:
            before_dot = s.split('.')[0]
            after_dot = s.split('.')[1]
            # noktadan sonra tam 3 rakam → binlik ayırıcı
            if re.fullmatch(r'\d{3}', after_dot) and len(before_dot) > 0 and all(c.isdigit() for c in before_dot):
                s = s.replace('.', '')
                try:
                    return float(s)
                except ValueError:
                    return None
            else:
                try:
                    return float(s)
                except ValueError:
                    return None
        else:
            # sadece rakam ve varsa tek nokta/virgül
            try:
                return float(s)
            except ValueError:
                return None
    return None

def parse_tarih(val):
    """tarihi YYYY-MM-DD formatında döndürür, geçersizse None."""
    if val is None or not isinstance(val, str):
        return None
    val = val.strip()
    if not val:
        return None

    # YYYY-MM-DD
    m = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', val)
    if m:
        try:
            datetime(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
        except ValueError:
            return None

    # YYYY/MM/DD
    m = re.fullmatch(r'(\d{4})/(\d{2})/(\d{2})', val)
    if m:
        try:
            datetime(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
        except ValueError:
            return None

    # GG.AA.YYYY
    m = re.fullmatch(r'(\d{2})\.(\d{2})\.(\d{4})', val)
    if m:
        try:
            datetime(int(m.group(3)), int(m.group(2)), int(m.group(1)))
            return f"{m.group(3)}-{m.group(2)}-{m.group(1)}"
        except ValueError:
            return None

    # Türkçe: G Ay YYYY (ör. "2 Nisan 2025", "30 Haziran 2025")
    m = re.fullmatch(r'(\d{1,2})\s+(Ay adı)\s+(\d{4})', val)

    return None

