with open("siparisler.jsonl") as f:
    satirlar = f.readlines()

for i, s in enumerate(satirlar):
    stripped = s.strip()
    if stripped == "":
        print(f"Satır {i+1}: BOŞ")
        continue
    try:
        d = json.loads(stripped)
        if isinstance(d, list):
            print(f"Satır {i+1}: JSON array")
        elif isinstance(d, dict):
            print(f"Satır {i+1}: id={d.get('id')}, keys={list(d.keys())}")
        else:
            print(f"Satır {i+1}: type={type(d)}")
    except json.JSONDecodeError:
        print(f"Satır {i+1}: PARSE HATA")
